CREATE OR REPLACE FUNCTION public.check_rate_limit(target_user_id uuid, endpoint_name text, max_requests integer DEFAULT 10, window_minutes integer DEFAULT 60)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  current_count integer;
  window_start_time timestamp with time zone;
BEGIN
  window_start_time := now() - (window_minutes || ' minutes')::interval;

  -- Get current request count in window
  SELECT COALESCE(SUM(request_count), 0)
  INTO current_count
  FROM public.rate_limits
  WHERE user_id = target_user_id
    AND endpoint = endpoint_name
    AND window_start > window_start_time;

  -- Clean old entries
  DELETE FROM public.rate_limits
  WHERE window_start < window_start_time;

  -- Check if under limit
  IF current_count >= max_requests THEN
    RETURN false;
  END IF;

  -- Record this request
  INSERT INTO public.rate_limits (user_id, endpoint, request_count, window_start)
  VALUES (target_user_id, endpoint_name, 1, now())
  ON CONFLICT DO NOTHING;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_verification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  privileged BOOLEAN := current_user NOT IN ('authenticated', 'anon');
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT privileged THEN
      NEW.is_verified := false;
      NEW.is_expert := false;
      NEW.verified_status := NULL;
      NEW.plan := 'free';
      NEW.pro_until := NULL;
      NEW.pro_source := NULL;
      NEW.pro_will_renew := NULL;
      NEW.stripe_customer_id := NULL;
    END IF;
  ELSE
    IF NOT privileged THEN
      NEW.is_verified := OLD.is_verified;
      NEW.is_expert := OLD.is_expert;
      IF NOT OLD.is_verified THEN
        NEW.verified_status := OLD.verified_status;
      END IF;
      NEW.plan := OLD.plan;
      NEW.pro_until := OLD.pro_until;
      NEW.pro_source := OLD.pro_source;
      NEW.pro_will_renew := OLD.pro_will_renew;
      NEW.stripe_customer_id := OLD.stripe_customer_id;
    END IF;
  END IF;
  IF NOT NEW.is_verified THEN
    NEW.verified_status := NULL;
  END IF;
  IF NEW.is_verified THEN
    NEW.is_public := true;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_restaurant_cuisine()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  privileged boolean := current_user NOT IN ('authenticated', 'anon');
BEGIN
  NEW.cuisine := btrim(coalesce(NEW.cuisine, ''));
  -- "Restaurant" is the non-answer this whole effort exists to remove;
  -- never let it be stored as if it were a cuisine.
  IF NEW.cuisine = '' OR lower(NEW.cuisine) = 'restaurant' THEN
    RETURN NULL;
  END IF;
  IF char_length(NEW.cuisine) > 60 THEN
    RETURN NULL;
  END IF;

  -- Tiers that mean "a human decided this" — or "a server went and
  -- looked" — are not things a client gets to assert.
  IF NOT privileged AND NEW.source IN ('approved', 'consensus', 'community', 'osm') THEN
    RETURN NULL;
  END IF;

  NEW.confidence := public.cuisine_source_confidence(NEW.source);
  IF NEW.confidence = 0 THEN
    RETURN NULL;
  END IF;
  NEW.updated_at := now();

  IF TG_OP = 'UPDATE' THEN
    -- Strictly weaker source: keep what's there.
    IF NEW.confidence < OLD.confidence THEN
      RETURN NULL;
    END IF;
    -- Same strength, same answer: nothing to write.
    IF NEW.confidence = OLD.confidence AND NEW.cuisine = OLD.cuisine THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_restaurant_cuisine_tags()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  privileged boolean := current_user NOT IN ('authenticated', 'anon');
  v_count integer;
BEGIN
  IF NOT privileged THEN
    RETURN NULL;
  END IF;

  NEW.cuisine := btrim(coalesce(NEW.cuisine, ''));
  IF NEW.cuisine = '' OR lower(NEW.cuisine) = 'restaurant' THEN
    RETURN NULL;
  END IF;
  IF char_length(NEW.cuisine) > 60 THEN
    RETURN NULL;
  END IF;
  IF NEW.source NOT IN ('approved', 'consensus') THEN
    RETURN NULL;
  END IF;

  -- Never duplicate the primary as a tag.
  IF EXISTS (
    SELECT 1 FROM public.restaurant_cuisine
     WHERE restaurant_id = NEW.restaurant_id
       AND lower(cuisine) = lower(NEW.cuisine)
  ) THEN
    RETURN NULL;
  END IF;

  -- The cap, enforced here rather than only in the caller, so no future
  -- path can add a fourth by forgetting to check.
  IF TG_OP = 'INSERT' THEN
    SELECT count(*) INTO v_count FROM public.restaurant_cuisine_tags
     WHERE restaurant_id = NEW.restaurant_id;
    -- +1 for the primary, which always occupies the first slot.
    IF v_count + 1 >= public.cuisine_max_count() THEN
      RETURN NULL;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_cuisine_suggestion_verdict()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status = 'pending' AND OLD.status <> 'pending' THEN
    NEW.reviewed_by := NULL;
    NEW.reviewed_at := NULL;
    NEW.deny_reason := NULL;
    NEW.created_at  := now();   -- it is a new proposal, and the queue sorts by age
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
